const { spawn } = require('child_process');
const http = require('http');

const edge = spawn('C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', [
  '--headless',
  '--remote-debugging-port=9223',
  '--window-size=375,800',
  'file:///C:/RL Multimodal/RL_Multimodal/RL Multimodal_Bright Nail Bar/Gemini_Bright Nail Bar/index.html'
]);

setTimeout(() => {
  http.get('http://127.0.0.1:9223/json', (res) => {
    let data = '';
    res.on('data', c => data += c);
    res.on('end', () => {
      const page = JSON.parse(data).find(p => p.title.includes('Bright Nail Bar'));
      if (!page) { edge.kill(); return; }
      const ws = new WebSocket(page.webSocketDebuggerUrl);
      ws.onopen = () => {
        ws.send(JSON.stringify({
          id: 1,
          method: 'Runtime.evaluate',
          params: {
            expression: \`(() => {
              const docWidth = document.documentElement.scrollWidth;
              const winWidth = window.innerWidth;
              const elements = Array.from(document.querySelectorAll('*')).map(el => {
                const rect = el.getBoundingClientRect();
                return {
                  tag: el.tagName,
                  id: el.id,
                  cls: el.className,
                  right: rect.right,
                  width: rect.width,
                  scrollWidth: el.scrollWidth
                };
              }).filter(e => e.right > winWidth + 1);
              return { docWidth, winWidth, overflowing: elements };
            })()\`,
            returnByValue: true
          }
        }));
      };
      ws.onmessage = (msg) => {
        const res = JSON.parse(msg.data);
        console.log(JSON.stringify(res.result.result.value, null, 2));
        ws.close();
        edge.kill();
      };
    });
  });
}, 1500);
"

