const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');

async function testViewport(width, height, name) {
  const port = 9400 + Math.floor(Math.random() * 100);
  const edge = spawn('C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', [
    '--headless',
    \`--remote-debugging-port=\${port}\`,
    'file:///C:/RL Multimodal/RL_Multimodal/RL Multimodal_Bright Nail Bar/Gemini_Bright Nail Bar/index.html'
  ]);

  await new Promise(r => setTimeout(r, 1200));

  return new Promise((resolve, reject) => {
    http.get(\`http://127.0.0.1:\${port}/json\`, res => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', async () => {
        const page = JSON.parse(data).find(p => p.title.includes('Bright Nail Bar'));
        if (!page) { edge.kill(); return resolve(); }
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        ws.onopen = () => {
          ws.send(JSON.stringify({
            id: 1,
            method: 'Emulation.setDeviceMetricsOverride',
            params: { width, height, deviceScaleFactor: 1, mobile: width < 768 }
          }));
        };
        ws.onmessage = (msg) => {
          const d = JSON.parse(msg.data);
          if (d.id === 1) {
            ws.send(JSON.stringify({
              id: 2,
              method: 'Page.captureScreenshot',
              params: { format: 'png', captureBeyondViewport: true }
            }));
          } else if (d.id === 2) {
            fs.writeFileSync(\`C:/Users/sures/AppData/Local/Temp/opencode/\${name}.png\`, Buffer.from(d.result.data, 'base64'));
            ws.close();
            edge.kill();
            resolve();
          }
        };
      });
    }).on('error', err => { edge.kill(); reject(err); });
  });
}

(async () => {
  await testViewport(375, 812, 'updated_mobile_375');
  await testViewport(768, 1024, 'updated_tablet_768');
  await testViewport(1280, 800, 'updated_desktop_1280');
  console.log('Updated screenshots saved successfully!');
})();
"

