const fs = require('fs');
const buf = fs.readFileSync('images/hero.jpg');
// Find SOF0 (0xFF, 0xC0) or SOF2 (0xFF, 0xC2)
let offset = 2;
while (offset < buf.length) {
  const marker = buf.readUInt16BE(offset);
  offset += 2;
  if (marker === 0xFFC0 || marker === 0xFFC2) {
    const h = buf.readUInt16BE(offset + 3);
    const w = buf.readUInt16BE(offset + 5);
    console.log('Hero dimensions:', w, 'x', h);
    break;
  }
  const len = buf.readUInt16BE(offset);
  offset += len;
}
"

